css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-mes {
  width: min(420px, 100%);
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  padding: 8px 12px; border: 1px solid var(--border); border-radius: 12px; background: var(--bg-surface);
}

.bs-mes-nav { display: flex; align-items: center; gap: 4px; flex: 1; min-width: 0; }

.bs-mes-seta {
  display: grid; place-items: center; flex-shrink: 0;
  width: 32px; height: 32px; border: none; border-radius: 8px;
  color: var(--text-muted); background: transparent;
}
.bs-mes-seta:hover { color: var(--text); background: var(--bg-card); }
.bs-mes-ic { width: 16px; height: 16px; }

/* flex: 1 + centro truncado: o nome do mês muda de largura e não pode
   empurrar as setas de lugar. */
.bs-mes-label {
  flex: 1; min-width: 0; text-align: center;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-family: var(--fonte-titulo); font-size: 13px; font-weight: 600; color: var(--text);
}
/* O rótulo e o "Hoje" sobem um passo a partir de 768px, como no app. */
@media (min-width: 768px) {
  .bs-mes-label { font-size: 14px; }
  .bs-mes-hoje { font-size: 12px; }
}

.bs-mes-hoje {
  flex-shrink: 0; padding: 6px 12px;
  border: 1px solid var(--border); border-radius: 8px; background: transparent;
  font-family: var(--fonte); font-size: 11px; font-weight: 600; color: var(--text-muted);
}
.bs-mes-hoje:hover { color: var(--text); border-color: var(--accent); }
.bs-mes-hoje[hidden] { display: none; }

js:
// Competência como 'AAAA-MM'. A aritmética é feita em número de mês (0-11),
// que é o que faz dezembro virar janeiro sem caso especial.
function deslocar(mes, passo) {
  const [ano, m] = mes.split('-').map(Number)
  const d = new Date(ano, m - 1 + passo, 1)
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0')
}

function rotulo(mes) {
  const [ano, m] = mes.split('-').map(Number)
  const texto = new Date(ano, m - 1, 1).toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' })
  return texto.charAt(0).toUpperCase() + texto.slice(1)
}

export function iniciarSeletorMes(raiz, atual, aoMudar) {
  const label = raiz.querySelector('.bs-mes-label')
  const hoje = raiz.querySelector('.bs-mes-hoje')

  function render() {
    const mes = raiz.dataset.mes
    label.textContent = rotulo(mes)
    // O "Hoje" só existe fora do mês corrente: botão inerte ensina o usuário
    // a ignorar o canto da tela.
    hoje.hidden = mes === atual
    aoMudar?.(mes)
  }

  raiz.querySelectorAll('.bs-mes-seta').forEach((btn) => {
    btn.addEventListener('click', () => {
      raiz.dataset.mes = deslocar(raiz.dataset.mes, Number(btn.dataset.passo))
      render()
    })
  })
  hoje.addEventListener('click', () => {
    raiz.dataset.mes = atual
    render()
  })

  render()
}
